const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let query='',filter='all';
function completed(id){try{return localStorage.getItem('grammar-completed-'+id)==='yes'}catch{return false}}
function navigation(id){document.querySelector('.side-bottom span').textContent=`依自備教材整理 · ${LESSONS.length} 個單元`;$('#nav').innerHTML=`<a href="#" class="${!id?'active':''}"><em>⌂</em>全部單元</a>`+LESSONS.map((l,i)=>`<a href="#${l.id}" class="${id===l.id?'active':''}" ${id===l.id?'aria-current="page"':''}><em>${String(i+1).padStart(2,'0')}</em>${esc(l.title)}</a>`).join('')}
function cards(){const ls=LESSONS.filter(l=>(filter==='all'||(filter==='basic'?l.level.includes('基礎'):l.level.includes('進階')))&&[l.title,l.en,l.intro].join(' ').toLowerCase().includes(query.toLowerCase()));$('#cards').innerHTML=ls.length?ls.map(l=>`<a class="card" href="#${l.id}"><div class="card-top"><span class="number">${String(LESSONS.indexOf(l)+1).padStart(2,'0')}</span><span class="tag">${esc(l.level)}</span></div><h3>${esc(l.title)}</h3><span class="en">${esc(l.en)}</span><p>${esc(l.intro)}</p><div class="card-foot"><span>${l.rules.length} 個重點 · ${l.quiz.length} 題練習${completed(l.id)?' · <span class="cleared">已練習 ✓</span>':''}</span><span class="arrow">進入關卡 ▸</span></div></a>`).join(''):'<p class="empty">找不到符合的單元，試試其他關鍵字。</p>'}
function home(){document.title='英文小教室｜文法學習筆記';$('#main').innerHTML=`<section class="hero"><div><span class="eyebrow">YOUR LITTLE GRAMMAR NOTEBOOK</span><h1>把英文文法，<br>一頁一頁<i>讀懂。</i></h1><p class="lead">從句子的骨架，到語氣裡的細節。<br>整理重點、讀懂例句，再用練習確認自己的理解。</p><div class="stats"><span><strong>${String(LESSONS.length).padStart(2,'0')}</strong>學習單元</span><span><strong>${LESSONS.reduce((n,l)=>n+l.quiz.length,0)}</strong>教材選題</span><span><strong>∞</strong>反覆練習</span></div></div><div class="notebook" aria-label="句型筆記裝飾"><div class="note-title">GRAMMAR QUEST / 文法冒險</div><div class="pixel-scene" aria-hidden="true"></div><div class="formula"><b>S</b> + V</div><div class="formula">S + <b>V</b> + O</div><div class="formula">S + V + <b>C</b></div><small>STEP BY STEP. YOU'VE GOT THIS.</small></div></section><section><div class="section-title"><h2>今天，從哪裡開始？</h2><span>CHOOSE YOUR LESSON / 選擇單元</span></div><div class="tools"><input id="search" type="search" placeholder="搜尋單元，例如：時態、子句…" aria-label="搜尋單元"><button class="chip selected" data-filter="all">全部</button><button class="chip" data-filter="basic">基礎</button><button class="chip" data-filter="advanced">進階</button></div><div id="cards" class="cards"></div></section><div class="info"><strong>這份筆記怎麼使用？</strong><br>先讀重點與例句 → 留意常見錯誤 → 挑戰關主 → 答對至少四題解鎖下一關。<br>題目節選自使用者提供的《文法(2).pdf》；白話講解、例句、答案與解析為另外整理，並非原教材附解。單元同時包含基礎與進階內容，可依程度選讀。</div>`;query='';filter='all';cards();$('#search').addEventListener('input',e=>{query=e.target.value;cards()});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));cards()}))}
function lesson(l){document.title=l.title+'｜英文小教室';const i=LESSONS.indexOf(l);$('#main').innerHTML=`<div class="breadcrumb"><a href="#">全部單元</a> / ${esc(l.title)}</div><section class="lesson-title"><span class="eyebrow">LESSON ${String(i+1).padStart(2,'0')} · ${esc(l.level)}</span><h1>${esc(l.title)}</h1><div class="en">${esc(l.en)}</div><p class="lead">${esc(l.intro)}</p></section><div class="lesson-tabs"><a href="#${l.id}/notes">01 重點講義</a><a href="#${l.id}/mistakes">02 常見錯誤</a><a href="#${l.id}/practice">03 隨堂練習</a></div><section id="notes" class="lesson-section"><h2>01 / 讀懂文法重點</h2><p class="source-note">以下為配合教材題目補充的說明與例句。</p>${l.rules.map(r=>`<article class="rule"><div><h3>${esc(r.form)}</h3><p>${esc(r.explain)}</p></div><div class="example">${esc(r.example)}<span>${esc(r.translation)}</span></div></article>`).join('')}</section><section id="mistakes" class="lesson-section"><h2>02 / 容易混淆的地方</h2><div class="mistake"><strong>先記住這個提醒</strong>${esc(l.mistake)}</div></section><section id="practice" class="lesson-section"><h2>03 / 換你試試看</h2><p class="source-note">節選教材題目，共 ${l.quiz.length} 題。每題作答後可看解析。答對至少四題即可通關。</p><form id="quiz"><div class="quest-progress"><progress id="quest-progress" max="${l.quiz.length}" value="0" aria-label="作答進度"></progress><span id="quest-count" aria-live="polite">已作答 0 / ${l.quiz.length} 題</span></div>${l.quiz.map((q,j)=>`<fieldset class="question"><legend>QUESTION ${String(j+1).padStart(2,'0')}</legend><div class="prompt">${esc(q.question)}</div><div class="options">${q.options.map((o,k)=>`<label><input type="radio" name="q${j}" value="${k}"><span>${'ABCD'[k]}. ${esc(o)}</span></label>`).join('')}</div><div id="a${j}" class="answer" hidden></div><div class="source">${esc(q.source)} · 解析為補充整理</div></fieldset>`).join('')}<div class="actions"><button type="submit" class="primary">提交並查看解析</button><button type="reset" class="secondary">重新練習</button><button type="button" class="pixel-button" id="jump-unanswered">找下一道未答題 ▸</button></div><div id="result" role="status" aria-live="polite"></div></form></section><div class="pager">${i?`<a href="#${LESSONS[i-1].id}">← ${esc(LESSONS[i-1].title)}</a>`:'<a href="#">← 回到首頁</a>'}${i<LESSONS.length-1?`<a href="#${LESSONS[i+1].id}">${esc(LESSONS[i+1].title)} →</a>`:'<a href="#">所有單元 →</a>'}</div>`;mountBoss(l);}
let current=null;function route(){const [id,section]=location.hash.slice(1).split('/');const l=LESSONS.find(x=>x.id===id);if(current!==(l?.id||'')){navigation(l?.id);l?lesson(l):home();current=l?.id||'';window.scrollTo(0,0)}if(section&&['notes','mistakes','practice'].includes(section))document.getElementById(section)?.scrollIntoView()}
window.addEventListener('hashchange',route);$('#print').addEventListener('click',()=>window.print());route();
